<!DOCTYPE html>
<html lang="zh-CN">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>趣聊 - 分享你的生活点滴</title>
    <style>
        :root {
            --primary: #3b82f6;
            --primary-hover: #2563eb;
            --bg-body: #f3f4f6;
            --bg-card: #ffffff;
            --text-main: #111827;
            --text-secondary: #6b7280;
            --border: #e5e7eb;
            --radius: 12px;
            --shadow: 0 1px 3px 0 rgba(0, 0, 0, 0.1), 0 1px 2px 0 rgba(0, 0, 0, 0.06);
        }

        * {
            box-sizing: border-box;
            margin: 0;
            padding: 0;
        }

        body {
            font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, "Noto Sans", sans-serif;
            background-color: var(--bg-body);
            color: var(--text-main);
            line-height: 1.5;
        }

        /* 顶部导航 */
        .navbar {
            background-color: var(--bg-card);
            border-bottom: 1px solid var(--border);
            position: sticky;
            top: 0;
            z-index: 100;
            padding: 0.75rem 0;
        }

        .nav-container {
            max-width: 1200px;
            margin: 0 auto;
            padding: 0 1.5rem;
            display: flex;
            align-items: center;
            justify-content: space-between;
        }

        .logo {
            font-size: 1.5rem;
            font-weight: 800;
            color: var(--primary);
            text-decoration: none;
            display: flex;
            align-items: center;
            gap: 0.5rem;
        }

        .search-bar {
            flex: 1;
            max-width: 400px;
            margin: 0 2rem;
            position: relative;
            display: none; /* Desktop hidden */
        }

        .search-input {
            width: 100%;
            padding: 0.6rem 1rem 0.6rem 2.5rem;
            border: 1px solid var(--border);
            border-radius: 99px;
            background: var(--bg-body);
            outline: none;
            font-size: 0.9rem;
        }

        .nav-actions {
            display: flex;
            gap: 1rem;
            align-items: center;
        }

        .nav-link {
            text-decoration: none;
            color: var(--text-secondary);
            font-weight: 500;
            padding: 0.5rem 1rem;
            border-radius: 8px;
            transition: background 0.2s;
            display: flex;
            align-items: center;
            gap: 0.5rem;
        }

        .nav-link:hover, .nav-link.active {
            background-color: #eff6ff;
            color: var(--primary);
        }

        .btn-primary {
            background-color: var(--primary);
            color: white;
            padding: 0.6rem 1.5rem;
            border-radius: 99px;
            text-decoration: none;
            font-weight: 600;
            border: none;
            cursor: pointer;
            transition: background 0.2s;
        }

        .btn-primary:hover {
            background-color: var(--primary-hover);
        }

        /* 主布局 */
        .layout {
            max-width: 1200px;
            margin: 1.5rem auto;
            padding: 0 1.5rem;
            display: grid;
            grid-template-columns: 240px 1fr 300px;
            gap: 1.5rem;
        }

        /* 左侧边栏 */
        .sidebar-left {
            position: sticky;
            top: 80px;
            height: fit-content;
        }

        .menu-item {
            display: flex;
            align-items: center;
            gap: 12px;
            padding: 0.75rem 1rem;
            border-radius: var(--radius);
            text-decoration: none;
            color: var(--text-main);
            font-weight: 500;
            margin-bottom: 0.5rem;
            transition: background 0.2s;
        }

        .menu-item:hover {
            background-color: rgba(0,0,0,0.04);
        }

        .menu-item.active {
            background-color: rgba(59, 130, 246, 0.1);
            color: var(--primary);
        }

        /* 中间内容区 */
        .content-area {
            display: flex;
            flex-direction: column;
            gap: 1.5rem;
        }

        .create-post {
            background: var(--bg-card);
            padding: 1rem;
            border-radius: var(--radius);
            box-shadow: var(--shadow);
        }

        .post-input {
            width: 100%;
            border: none;
            background: var(--bg-body);
            padding: 0.75rem;
            border-radius: var(--radius);
            resize: none;
            height: 80px;
            font-family: inherit;
            outline: none;
            margin-bottom: 0.75rem;
        }

        .post-input:focus {
            background: #e5e7eb;
        }

        .post-actions {
            display: flex;
            justify-content: space-between;
            align-items: center;
            border-top: 1px solid var(--border);
            padding-top: 0.75rem;
        }

        .post-tools {
            display: flex;
            gap: 0.5rem;
        }

        .tool-btn {
            background: none;
            border: none;
            cursor: pointer;
            color: var(--text-secondary);
            padding: 0.4rem;
            border-radius: 6px;
            transition: background 0.2s;
        }

        .tool-btn:hover {
            background: rgba(0,0,0,0.05);
        }

        /* 帖子卡片 */
        .post-card {
            background: var(--bg-card);
            border-radius: var(--radius);
            box-shadow: var(--shadow);
            overflow: hidden;
            animation: fadeIn 0.5s ease;
        }

        @keyframes fadeIn {
            from { opacity: 0; transform: translateY(10px); }
            to { opacity: 1; transform: translateY(0); }
        }

        .post-header {
            padding: 1rem;
            display: flex;
            align-items: center;
            justify-content: space-between;
        }

        .user-info {
            display: flex;
            align-items: center;
            gap: 10px;
        }

        .avatar {
            width: 48px;
            height: 48px;
            border-radius: 50%;
            object-fit: cover;
            background: #ddd;
        }

        .user-meta h4 {
            font-size: 1rem;
            font-weight: 600;
        }

        .user-meta span {
            font-size: 0.85rem;
            color: var(--text-secondary);
        }

        .post-content {
            padding: 0 1rem 1rem 1rem;
            font-size: 1rem;
        }

        .post-image {
            width: 100%;
            height: auto;
            display: block;
            background: #f0f0f0;
            cursor: pointer;
        }

        .post-stats {
            padding: 0.75rem 1rem;
            display: flex;
            justify-content: space-between;
            color: var(--text-secondary);
            font-size: 0.9rem;
            border-bottom: 1px solid var(--border);
        }

        .stat-item {
            display: flex;
            align-items: center;
            gap: 5px;
        }

        .post-footer {
            display: grid;
            grid-template-columns: 1fr 1fr;
        }

        .action-btn {
            background: none;
            border: none;
            padding: 0.75rem;
            font-size: 0.95rem;
            color: var(--text-secondary);
            cursor: pointer;
            border-radius: 0;
            display: flex;
            align-items: center;
            justify-content: center;
            gap: 8px;
            transition: background 0.2s;
        }

        .action-btn:hover {
            background-color: #f3f4f6;
        }

        .action-btn.liked {
            color: #ef4444;
        }

        /* 右侧边栏 */
        .sidebar-right {
            position: sticky;
            top: 80px;
            height: fit-content;
        }

        .widget {
            background: var(--bg-card);
            border-radius: var(--radius);
            padding: 1.25rem;
            box-shadow: var(--shadow);
            margin-bottom: 1.5rem;
        }

        .widget-title {
            font-size: 1rem;
            font-weight: 700;
            margin-bottom: 1rem;
            padding-bottom: 0.5rem;
            border-bottom: 1px solid var(--border);
        }

        .trend-item {
            display: block;
            margin-bottom: 1rem;
            text-decoration: none;
        }

        .trend-item:last-child {
            margin-bottom: 0;
        }

        .trend-name {
            font-size: 0.85rem;
            color: var(--text-secondary);
            margin-bottom: 2px;
        }

        .trend-count {
            font-size: 0.95rem;
            font-weight: 600;
        }

        .suggestion-item {
            display: flex;
            align-items: center;
            justify-content: space-between;
            margin-bottom: 1rem;
        }

        .suggestion-info {
            display: flex;
            align-items: center;
            gap: 10px;
        }

        .btn-small {
            padding: 0.4rem 1rem;
            font-size: 0.85rem;
            border-radius: 99px;
            border: 1px solid var(--border);
            background: white;
            cursor: pointer;
            color: var(--text-main);
        }

        .btn-small:hover {
            background: #f3f4f6;
        }

        /* 响应式适配 */
        @media (min-width: 768px) {
            .search-bar {
                display: block;
            }
            .nav-actions .btn-primary {
                display: none;
            }
        }

        @media (max-width: 1024px) {
            .layout {
                grid-template-columns: 80px 1fr;
            }
            .sidebar-right {
                display: none;
            }
        }

        @media (max-width: 600px) {
            .layout {
                grid-template-columns: 1fr;
            }
            .sidebar-left {
                display: none;
            }
            .nav-link span {
                display: none;
            }
            .nav-actions {
                margin-left: auto;
            }
        }
    </style>
</head>
<body>

    <!-- 顶部导航 -->
    <nav class="navbar">
        <div class="nav-container">
            <a href="index.html" class="logo">
                <svg width="28" height="28" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round">
