            </article>
        </main>

        <!-- 右侧推荐 -->
        <aside class="sidebar-right">
            <div class="widget">
                <h3 class="widget-title">大家都在看</h3>
                <a href="#" class="trend-item">
                    <span class="trend-name">热门话题 · 电影</span>
                    <span class="trend-count">#周末看什么电影#</span>
                </a>
                <a href="#" class="trend-item">
                    <span class="trend-name">热门话题 · 音乐</span>
                    <span class="trend-count">#周杰伦新歌#</span>
                </a>
